func Tally(words []string) map[string]int {
	counts := make(map[string]int, len(words))
	for _, w := range words {
		counts[strings.ToLower(w)]++
	}
	return counts
}

type Counter struct {
	mu     sync.Mutex
	counts map[string]int
}

func (c *Counter) Add(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.counts[key]++
}

func worker(ctx context.Context, jobs <-chan Job, out chan<- Result) {
	for {
		select {
		case job, ok := <-jobs:
			if !ok {
				return
			}
			out <- Result{ID: job.ID, Err: job.Run(ctx)}
		case <-ctx.Done():
			return
		}
	}
}

type ParseError struct {
	Line int
	Err  error
}

func (e *ParseError) Error() string {
	return fmt.Sprintf("line %d: %v", e.Line, e.Err)
}

func (e *ParseError) Unwrap() error { return e.Err }

type Store interface {
	Get(ctx context.Context, id string) (User, error)
	Close() error
}

func withStore(s Store, fn func(Store) error) (err error) {
	defer func() {
		if cerr := s.Close(); err == nil {
			err = cerr
		}
	}()
	return fn(s)
}

func TestNormalize(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"trims", "  go ", "go"},
		{"lowers", "GO", "go"},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := Normalize(tc.in); got != tc.want {
				t.Errorf("got %q, want %q", got, tc.want)
			}
		})
	}
}

func statsHandler(store Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		stats, err := store.Stats(r.Context())
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		if err := json.NewEncoder(w).Encode(stats); err != nil {
			log.Printf("encode stats: %v", err)
		}
	}
}

func fanIn(ctx context.Context, srcs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	for _, src := range srcs {
		wg.Add(1)
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c {
				select {
				case out <- v:
				case <-ctx.Done():
					return
				}
			}
		}(src)
	}
	go func() {
		wg.Wait()
		close(out)
	}()
	return out
}

func GroupBy[T any, K comparable](items []T, key func(T) K) map[K][]T {
	out := make(map[K][]T)
	for _, item := range items {
		k := key(item)
		out[k] = append(out[k], item)
	}
	return out
}

func Keys[K comparable, V any](m map[K]V) []K {
	out := make([]K, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

func fetchAll(ctx context.Context, urls []string) ([]*http.Response, error) {
	g, ctx := errgroup.WithContext(ctx)
	g.SetLimit(runtime.NumCPU())
	out := make([]*http.Response, len(urls))

	for i, url := range urls {
		g.Go(func() error {
			req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
			if err != nil {
				return fmt.Errorf("build %s: %w", url, err)
			}
			res, err := http.DefaultClient.Do(req)
			if err != nil {
				return fmt.Errorf("get %s: %w", url, err)
			}
			out[i] = res
			return nil
		})
	}

	return out, g.Wait()
}

func rateLimit(ctx context.Context, in <-chan Job, every time.Duration) <-chan Job {
	out := make(chan Job)
	ticker := time.NewTicker(every)

	go func() {
		defer close(out)
		defer ticker.Stop()
		for job := range in {
			select {
			case <-ticker.C:
				out <- job
			case <-ctx.Done():
				return
			}
		}
	}()

	return out
}

type Shape interface {
	Area() float64
}

type Rect struct{ W, H float64 }
type Circle struct{ R float64 }

func (r Rect) Area() float64   { return r.W * r.H }
func (c Circle) Area() float64 { return math.Pi * c.R * c.R }

func Describe(s Shape) (string, error) {
	switch v := s.(type) {
	case Rect:
		return fmt.Sprintf("rect %.1fx%.1f", v.W, v.H), nil
	case Circle:
		return fmt.Sprintf("circle r=%.1f", v.R), nil
	default:
		return "", fmt.Errorf("unsupported shape %T", s)
	}
}
